SELECT ppcw.id, ppcw.amount, ppcw.add_time, ppcw.is_succeed, ppcw.bankflow, ppcw.con, ppcw.bank, ppcw.cardno, ppcw.cardname, ppcw.fee, ppcw.remark, ppcw.settlement_order_id, ppcw.pay_amount FROM ${database.prefix.payment}hou_pay_consume_withdraw ppcw WHERE ppcw.pay_uid = #{paraMap.userId}
and ppcw.is_succeed is not null
and ppcw.is_succeed = #{paraMap.otherStatus}
and ppcw.settlement_order_id like concat('%' ,#{paraMap.statementNo} ,'%')
and ppcw.add_time >= #{paraMap.startTime}
and ppcw.add_time <= #{paraMap.endTime}
and ppcw.withdraw_type = #{paraMap.settleType}
order by ppcw.add_time desc

SELECT ppcw.id, ppcw.amount, ppcw.add_time, ppcw.censor, ppcw.check_time, ppcw.is_succeed, ppcw.bankflow, ppcw.con, ppcw.bank, ppcw.cardno, ppcw.cardname, ppcw.fee, ppcw.remark, ppcw.shop_name, ppcw.user_name, ppcw.settlement_order_id, ppcw.pay_amount FROM ${database.prefix.payment}hou_pay_consume_withdraw ppcw
and ppcw.is_succeed = #{param.type}
and ppcw.user_name like concat ('%', #{param.userName},'%')
and ppcw.shop_name like concat ('%', #{param.shopName},'%')
and ppcw.settlement_order_id like concat ('%', #{param.statementNo},'%')
and ppcw.add_time >= #{param.startTime}
and ppcw.add_time <= #{param.endTime}
order by ppcw.add_time desc limit 6000

